import jsonfrom datetime import *from unicodedata import categoryclass Task:    def __init__(self, title, description, created_at, deadline, status, priority):        self.title = title        self.description = description        self.created_at = created_at        self.deadline = deadline        self.status = status        self.priority = priority        self._progress = 0    def mark_as_done(self):        self.status = 'выполнено'    def is_overdue(self):        return self.deadline < datetime.datetime.now().date()    def __str__(self):        return "".join([            f'Название: {self.title}, ',            f'Описание: {self.description}, ',            f'Создана: {self.created_at}, ',            f'Сделать до: {self.deadline}, ',            f'Статус: {self.status}, ',            f'Приоритет: {self.priority}'        ])    @property    def progress(self):        return self._progress    def update_progress(self, value):        if value > 100 or value < 0:            print('Так нельзя')        self._progress = value        if self._progress ==100:            self.status = 'выполнено'class WorkTask(Task):    def __init__(self, title, description, created_at, deadline, status, priority,project_name):        super().__init__(title, description, created_at, deadline, status,priority)        self.project_name = project_nameclass PersonalTask(Task):    def __init__(self, title, description, created_at, deadline, status, priority,category):        super().__init__(title, description, created_at, deadline, status,priority)        self.project_name = categoryclass TaskManager:    def __init__(self):        self.dict_tasks = {}    def add_task(self, task):        self.dict_tasks[task.title] = {}        self.dict_tasks[task.title]['description'] = task.description        self.dict_tasks[task.title]['deadline'] = task.deadline        self.dict_tasks[task.title]['status'] = task.status        self.dict_tasks[task.title]['priority'] = task.priority        self.dict_tasks[task.title]['created_at'] = task.created_at    def del_task(self, title):        self.dict_tasks.pop(title)    def list_tasks(self):        return self.dict_tasks    def list_overdue_tasks(self):        self.dict_overdue_tasks = {}        for task in self.dict_tasks.keys():            if datetime.strptime(self.dict_tasks[task]['deadline'],'%Y-%m-%d').date() < datetime.now().date():                self.dict_overdue_tasks[task.title] = self.dict_tasks[task]        return self.dict_overdue_tasks    def save_to_file(self, filename):        with open(f'{filename}.json', 'w',encoding="UTF-8") as file:            json.dump(self.dict_tasks, file)        self.dict_done_tasks = {}        for task in self.dict_tasks.keys():            if str(self.dict_tasks[task]['status']) == 'выполнено':                self.dict_done_tasks[task.title] = {}                self.dict_done_tasks[task.title]['description'] = task.description                self.dict_done_tasks[task.title]['deadline'] = task.deadline                self.dict_done_tasks[task.title]['status'] = task.status                self.dict_done_tasks[task.title]['priority'] = task.priority                self.dict_done_tasks[task.title]['created_at'] = task.created_at        with open(f'done_tasks.json', 'w',encoding="UTF-8") as file:            json.dump(self.dict_tasks, file)    def load_from_file(self, filename):        with open(f'{filename}.json', 'r',encoding="UTF-8") as file:            self.dict_tasks = json.load(file)manager = TaskManager()# task111 = WorkTask('sad','asd','2013-01-01','2025-01-01','in progress', 'low','1')# ta.add_task(task111, task111.__str__())# print(ta.list_tasks())# ta.list_overdue_tasks()## ta.save_to_file('task.json')# print(task111.progress)def get_priority_from_string(priority):    if 'высокий' in priority:        return 0    elif 'средний' in priority:        return 1    else:        return 2while 1:    print('1.Вывести задачи',          '2.Добавить задачу',          '3. Удалить задачу',          '4. Сохранить',          '5. Импорт'          '6. Только просроченные задачи', sep='\n')    user_choise = int(input(': '))    if user_choise == 1:        print(sorted(manager.list_tasks(), key=lambda task: get_priority_from_string(task), reverse=True))    elif user_choise == 2:        title= input('Название: ')        description= input('Описание: ')        created_at= input('Создан (в формате YYYY-MM-DD): ')        deadline= input('Сделать до (в формате YYYY-MM-DD): ')        print('Статус:',              '1.новая',              '2.в процессе',              '3.выполнено',sep='\n')        status = int(input(': '))        if status == 1:            status = 'новая'        elif status == 2:            status = 'в процессе'        else:            status = 'выполнено'        print('Приоритет:',              '1.низкий',              '2.средний',              '3.высокий', sep='\n')        priority = int(input(': '))        if priority == 1:            priority = 'низкий'        elif priority == 2:            priority = 'средний'        else:            priority = 'высокий'        print('1. Personal Task',              '2. Work Task',              sep='\n')        view = int(input(': '))        if view == 1:            category= input('Категория: ')            task = PersonalTask(title, description, created_at, deadline, status, priority,category)        else:            project_name = input('Имя проекта: ')            task = WorkTask(title, description, created_at, deadline, status, priority,project_name)        manager.add_task(task)    elif user_choise == 3:        title = input('Название задачи: ')        manager.del_task(title)    elif user_choise == 4:        name_file = input('Название файла: ')        manager.save_to_file(name_file)    elif user_choise == 5:        name_file = input('Название файла: ')        manager.load_from_file(name_file)    elif user_choise == 6:        print(sorted(manager.list_overdue_tasks(), key=lambda task: get_priority_from_string(task), reverse=True))